/* Candidate only: one iteration on a saved steady solution, then native scalar
 * residual export in the SAME process. Requires a separately authorized request.
 * No initialization, meshing, numerical/physical model edits or .sim save.
 * API: installed 20.02.008 CoupledSolver/SegregatedFlowSolver/
 * ScalarSolverBaseNoUrf::setLeaveTemporaryStorage and SimulationIterator::step.
 */
import java.io.*;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;
import java.security.MessageDigest;
import java.util.*;
import star.common.*;
import star.base.neo.ClientServerObject;
import star.base.report.*;
import star.coupledflow.CoupledSolver;
import star.segregatedflow.SegregatedFlowSolver;

public class ProbeNativeResidualSpatial extends StarMacro {
    private static final String COMPLETE="NATIVE_RESIDUAL_SPATIAL_PROBE_COMPLETE";
    private static String env(String k){String v=System.getenv(k);if(v==null||v.isEmpty())throw new IllegalArgumentException("Missing "+k);return v;}
    private static String base(String v){if(!v.matches("[a-zA-Z0-9_-]+"))throw new IllegalArgumentException("Unsafe basename");return v;}
    private static String q(String v){StringBuilder b=new StringBuilder("\"");for(char c:v.toCharArray()){if(c=='"'||c=='\\')b.append('\\').append(c);else if(c<32)b.append(String.format("\\u%04x",(int)c));else b.append(c);}return b.append('"').toString();}
    private static long count(String k){String x=env(k);if(!x.matches("[0-9]+"))throw new IllegalArgumentException("Invalid "+k);return Long.parseLong(x);}
    private static String sha(File f)throws Exception{if(!Files.isRegularFile(f.toPath(),LinkOption.NOFOLLOW_LINKS))throw new IOException("Regular non-link input required");MessageDigest d=MessageDigest.getInstance("SHA-256");try(InputStream in=Files.newInputStream(f.toPath())){byte[] b=new byte[1048576];int n;while((n=in.read(b))>0)d.update(b,0,n);}StringBuilder s=new StringBuilder();for(byte x:d.digest())s.append(String.format("%02x",x&255));return s.toString();}
    private static void pin(File f,String h)throws Exception{if(!h.matches("[a-f0-9]{64}")||!sha(f).equals(h))throw new IllegalStateException("Input SHA mismatch: "+f.getName());}
    private static File owned(File dir,String name)throws Exception{File f=new File(dir,name);if(!f.getCanonicalFile().getParentFile().equals(dir.getCanonicalFile())||Files.exists(f.toPath(),LinkOption.NOFOLLOW_LINKS))throw new IllegalStateException("Unsafe/existing output");return f;}
    private static void write(File dir,String name,String text)throws Exception{Files.writeString(owned(dir,name).toPath(),text,StandardCharsets.UTF_8,StandardOpenOption.CREATE_NEW);}
    static String iterationDeltaJson(long entry,long actual){return entry>=0&&actual>=entry?Long.toString(actual-entry):"null";}
    private static boolean number(double x){return Double.isFinite(x)&&Math.abs(x)<1e299;}
    private static String num(double x){return number(x)?Double.toString(x):"null";}
    private static Boolean retention(Solver x){if(x instanceof CoupledSolver)return ((CoupledSolver)x).getLeaveTemporaryStorage();if(x instanceof SegregatedFlowSolver)return ((SegregatedFlowSolver)x).getLeaveTemporaryStorage();if(x instanceof ScalarSolverBaseNoUrf)return ((ScalarSolverBaseNoUrf)x).getLeaveTemporaryStorage();return null;}
    private static void retain(Solver x,boolean value){if(x instanceof CoupledSolver)((CoupledSolver)x).setLeaveTemporaryStorage(value);else if(x instanceof SegregatedFlowSolver)((SegregatedFlowSolver)x).setLeaveTemporaryStorage(value);else if(x instanceof ScalarSolverBaseNoUrf)((ScalarSolverBaseNoUrf)x).setLeaveTemporaryStorage(value);else throw new IllegalArgumentException("Unsupported solver");}
    private static String meshState(Simulation s,FvRepresentation v){StringBuilder b=new StringBuilder();b.append(v.getCellCount()).append('|').append(v.getVertexCount()).append('|').append(v.getInteriorFaceCount()).append('|').append(s.getInterfaceManager().getObjects().size());for(Region r:s.getRegionManager().getRegions()){b.append('|').append(r.getPresentationName()).append(Arrays.toString(s.getMeshManager().getRegionExtents(r)));FvRegion fv=v.getFvRegionManager().getFvRegion(r);b.append(':').append(fv.getCellCount());for(Boundary x:r.getBoundaryManager().getBoundaries())b.append('|').append(x.getPresentationName()).append(':').append(x.getBoundaryType().getClass().getName()).append(':').append(fv.getFvBoundaries().getFvBoundary(x).getFaceCount()).append(':').append(x.getDependentInterfaces().size());}for(Continuum c:s.getContinuumManager().getObjects()){b.append('|').append(c.getClass().getName()).append(':').append(c.getPresentationName());if(c instanceof PhysicsContinuum)for(Model m:((PhysicsContinuum)c).getModelManager().getObjects())b.append(':').append(m.getClass().getName());}return b.toString();}
    private static FieldFunction nativeScalar(Simulation s,FvRepresentation v,String name,Class<?> exact){FieldFunction f=s.getFieldFunctionManager().getFunction(name);if(f==null||f instanceof UserFieldFunction||!name.equals(f.getFunctionName())||f.getTypeAsEnum()!=FieldFunctionTypeOption.Type.SCALAR||!f.isBoundToRepresentation(v)||(exact!=null&&!f.getClass().equals(exact)))throw new IllegalStateException("Native scalar unavailable: "+name);return f;}
    private static String fields(Collection<FieldFunction> fs){StringBuilder b=new StringBuilder("[");for(FieldFunction f:fs){if(b.length()>1)b.append(',');b.append("{\"name\":").append(q(f.getFunctionName())).append(",\"label\":").append(q(f.getPresentationName())).append(",\"native_type\":").append(q(String.valueOf(f.getTypeAsEnum()))).append(",\"class\":").append(q(f.getClass().getName())).append('}');}return b.append(']').toString();}
    private static double extreme(Simulation s,FvRepresentation v,FieldFunction f,boolean minimum,List<ClientServerObject> tmp){ScalarReport r=minimum?s.getReportManager().createReport(MinReport.class):s.getReportManager().createReport(MaxReport.class);tmp.add(r);r.setRepresentation(v);r.setFieldFunction(f);r.getParts().setObjects(s.getRegionManager().getRegions());double x=r.getReportMonitorValue();s.deleteObjects(Collections.singletonList(r));tmp.remove(r);return x;}
    private static String export(Simulation s,FvRepresentation v,Region region,List<FieldFunction> fs,File dir,String name,long expected,List<ClientServerObject> tmp)throws Exception{for(FieldFunction f:fs)if(f.getTypeAsEnum()!=FieldFunctionTypeOption.Type.SCALAR)throw new IllegalStateException("Non-scalar XYZ field");XyzInternalTable t=s.getTableManager().createTable(XyzInternalTable.class);tmp.add(t);t.setRepresentation(v);t.getParts().setObjects(region);t.setExtractVertexData(false);t.setFieldFunctions(fs);t.extract();long n=t.getRowCount();if(n!=expected||n<=0)throw new IllegalStateException("Native/CSV coverage differs");File out=owned(dir,name);t.export(out.getAbsolutePath());if(out.length()==0||out.length()>2147483648L)throw new IllegalStateException("Empty/oversize export");String result="{\"file\":"+q(name)+",\"rows\":"+n+",\"sha256\":"+q(sha(out))+",\"fields\":"+fields(fs)+"}";s.deleteObjects(Collections.singletonList(t));tmp.remove(t);return result;}
    @Override public void execute(){Simulation s=getActiveSimulation();File dir=s.getSessionDirFile(),source=null;FvRepresentation v=null;String phase="guards";boolean verifiedDir=false,retentionRestored=false,stepAttempted=false;long start=-1,expected=-1,entryIteration=s.getSimulationIterator().getCurrentIteration();Exception failure=null;List<ClientServerObject> tmp=new ArrayList<>();Map<Solver,Boolean> prior=new LinkedHashMap<>();try{
        String run=base(env("RP_RUN_ID")),sourceBase=base(env("RP_SOURCE_BASE"));
        if(!"EXPLICIT_ONE_ITERATION_DIAGNOSTIC_V1".equals(env("RP_EXECUTION_AUTHORIZATION"))||count("RP_ALLOWED_ADDITIONAL_ITERATIONS")!=1)throw new IllegalStateException("Explicit one-iteration diagnostic authorization required");
        if(!dir.getCanonicalPath().equals("C:\\CodexCFDRestricted\\"+run)||!dir.getCanonicalFile().equals(new File(env("AIR3B_JOB_DIR")).getCanonicalFile()))throw new IllegalStateException("Wrong isolated directory");verifiedDir=true;
        source=new File(dir,sourceBase+".sim");if(!new File(s.getSessionPath()).getCanonicalFile().equals(source.getCanonicalFile()))throw new IllegalStateException("Wrong loaded source");pin(source,env("RP_SOURCE_SHA"));pin(new File(dir,"case_spec.json"),env("RP_SPEC_SHA"));
        expected=count("RP_EXPECTED_CELLS");start=count("RP_EXPECTED_ITERATION");v=(FvRepresentation)s.getRepresentationManager().getObject("Volume Mesh");
        if(v==null||!v.is3D()||v.isAtLeastOne2D()||expected<1||expected>3000000||v.getCellCount()!=expected||start<1||s.getSimulationIterator().getCurrentIteration()!=start||s.getSolution().getPhysicalTime()!=0)throw new IllegalStateException("Unexpected steady saved solution");
        if(s.getSimulationIterator().getAutoSave().getEnabled()||s.getSimulationIterator().getAutoExport().getEnabled())throw new IllegalStateException("Enabled automatic save/export is outside this diagnostic; refusing before iteration");
        int pc=0;for(Continuum c:s.getContinuumManager().getObjects())if(c instanceof PhysicsContinuum){pc++;boolean steady=false;for(Model m:((PhysicsContinuum)c).getModelManager().getObjects())if(m.getClass().getName().equals("star.common.SteadyModel"))steady=true;if(!steady)throw new IllegalStateException("Only steady physics continua supported");}if(pc==0)throw new IllegalStateException("No physics continuum");
        String before=meshState(s,v);boolean flagBefore=s.getSolution().isInitialized();FieldFunction pressure=nativeScalar(s,v,"Pressure",null);double pressureMin=extreme(s,v,pressure,true,tmp),pressureMax=extreme(s,v,pressure,false,tmp);if(!number(pressureMin)||!number(pressureMax)||Math.max(Math.abs(pressureMin),Math.abs(pressureMax))==0)throw new IllegalStateException("Saved pressure cannot establish a usable restart field");
        write(dir,"residual-probe-before.json","{\"status\":\"DIAGNOSTIC_ONLY\",\"loaded_iteration\":"+start+",\"loaded_cells\":"+expected+",\"initialized_flag\":"+flagBefore+",\"pressure_min\":"+num(pressureMin)+",\"pressure_max\":"+num(pressureMax)+",\"new_solver_iterations\":0}");
        phase="enable_storage";StringBuilder storage=new StringBuilder("[");boolean flow=false;
        for(Solver x:s.getSolverManager().getObjects()){Boolean old=retention(x);if(storage.length()>1)storage.append(',');storage.append("{\"class\":").append(q(x.getClass().getName())).append(",\"supported\":").append(old!=null);if(old!=null){prior.put(x,old);retain(x,true);if(!Boolean.TRUE.equals(retention(x)))throw new IllegalStateException("Storage setting did not take effect");storage.append(",\"before\":").append(old).append(",\"during_probe\":true");if(x instanceof CoupledSolver||x instanceof SegregatedFlowSolver)flow=true;}storage.append('}');}storage.append(']');if(!flow)throw new IllegalStateException("No audited flow-solver storage API");write(dir,"residual-probe-storage.json","{\"status\":\"DIAGNOSTIC_ONLY\",\"solvers\":"+storage+"}");
        phase="single_iteration";stepAttempted=true;s.getSimulationIterator().step(1);
        long end=s.getSimulationIterator().getCurrentIteration();if(end!=start+1||s.getSolution().getPhysicalTime()!=0||!before.equals(meshState(s,v)))throw new IllegalStateException("Iteration delta or structural state differs");
        phase="native_residual_inventory";List<FieldFunction> residuals=new ArrayList<>(),volume=new ArrayList<>();volume.add(nativeScalar(s,v,"CellQuality",CellQualityFunction.class));volume.add(nativeScalar(s,v,"FaceValidity",FaceValidityFunction.class));volume.add(nativeScalar(s,v,"VolumeChange",VolumeChangeFunction.class));
        List<FieldFunction> bound=new ArrayList<>(s.getFieldFunctionManager().getScalarFieldFunctions(v));for(String name:new String[]{"WallDistance","PrismLayerNumber","Volume","Pressure"})for(FieldFunction f:bound)if(name.equals(f.getFunctionName())&&!(f instanceof UserFieldFunction)&&f.getTypeAsEnum()==FieldFunctionTypeOption.Type.SCALAR&&f.isBoundToRepresentation(v)&&!volume.contains(f))volume.add(f);
        for(FieldFunction f:bound)if(!(f instanceof UserFieldFunction)&&f.isBoundToRepresentation(v)&&f.getTypeAsEnum()==FieldFunctionTypeOption.Type.SCALAR&&f.getFunctionName().endsWith("Residual")&&!residuals.contains(f)){residuals.add(f);if(residuals.size()>16)throw new IllegalStateException("Residual export field cap exceeded");volume.add(f);}
        write(dir,"residual-probe-field-inventory.json","{\"status\":\"DIAGNOSTIC_ONLY\",\"sample_iteration\":"+end+",\"residual_fields\":"+fields(residuals)+",\"bound_native_scalar_candidates\":"+fields(bound)+"}");
        if(residuals.isEmpty())throw new IllegalStateException("No native residual after one step; no automatic additional iteration");
        StringBuilder ranges=new StringBuilder("[");int nonzero=0;for(FieldFunction f:residuals){double lo=extreme(s,v,f,true,tmp),hi=extreme(s,v,f,false,tmp);if(ranges.length()>1)ranges.append(',');boolean ok=number(lo)&&number(hi)&&Math.max(Math.abs(lo),Math.abs(hi))>0;if(ok)nonzero++;ranges.append("{\"field\":").append(q(f.getFunctionName())).append(",\"min\":").append(num(lo)).append(",\"max\":").append(num(hi)).append(",\"finite_nonzero_range\":").append(ok).append('}');}ranges.append(']');if(nonzero==0)throw new IllegalStateException("All residual candidates invalid or zero; no automatic additional iteration");
        phase="cell_centred_export";StringBuilder exports=new StringBuilder("[");long total=0;int i=0;for(Region r:s.getRegionManager().getRegions()){if(!v.describesRegion(r))throw new IllegalStateException("Region missing from volume mesh");long n=v.getFvRegionManager().getFvRegion(r).getCellCount();if(exports.length()>1)exports.append(',');exports.append("{\"region\":").append(q(r.getPresentationName())).append(",\"location\":\"VOLUME_CELL_CENTRES\",\"table\":").append(export(s,v,r,volume,dir,"residual-spatial-r"+i+".csv",n,tmp)).append('}');total+=n;i++;}exports.append(']');if(total!=expected)throw new IllegalStateException("Global CSV coverage differs");
        phase="restore_and_postconditions";for(Map.Entry<Solver,Boolean> e:prior.entrySet()){retain(e.getKey(),e.getValue());if(!e.getValue().equals(retention(e.getKey())))throw new IllegalStateException("Storage restore mismatch");}retentionRestored=true;
        if(!tmp.isEmpty()||!before.equals(meshState(s,v))||s.getSimulationIterator().getCurrentIteration()!=end||s.getSolution().getPhysicalTime()!=0)throw new IllegalStateException("Post-export state differs");pin(source,env("RP_SOURCE_SHA"));pin(new File(dir,"case_spec.json"),env("RP_SPEC_SHA"));
        write(dir,"native_residual_spatial_probe.json","{\"status\":\"ok\",\"scope\":\"ONE_NEW_ITERATION_NATIVE_SPATIAL_DIAGNOSTIC\",\"run_id\":"+q(run)+",\"source_sha256\":"+q(env("RP_SOURCE_SHA"))+",\"spec_sha256\":"+q(env("RP_SPEC_SHA"))+",\"cells\":"+total+",\"start_iteration\":"+start+",\"sample_iteration\":"+end+",\"new_solver_iterations\":1,\"initialized_flag_before\":"+flagBefore+",\"initialized_flag_after\":"+s.getSolution().isInitialized()+",\"explicit_initialization_calls\":0,\"new_meshes\":0,\"explicit_sim_saves\":0,\"automatic_save_export_disabled_before_step\":true,\"source_bytes_unchanged\":true,\"structural_state_unchanged\":true,\"storage_restored\":true,\"native_residual_field_count\":"+residuals.size()+",\"finite_nonzero_range_field_count\":"+nonzero+",\"ranges\":"+ranges+",\"exports\":"+exports+",\"sample_is_original_saved_iteration\":false,\"all_cell_values_validated\":false,\"native_cell_ids_verified\":false,\"global_monitor_normalization_equivalence_verified\":false,\"causality_established\":false,\"engineering_verified\":false,\"complete_marker\":"+q(COMPLETE)+"}");s.println(COMPLETE);
    }catch(Exception e){failure=e;throw new RuntimeException("Residual probe failed at "+phase,e);
    }finally{
        StringBuilder cleanup=new StringBuilder("[");boolean cleanupOk=true;
        for(Map.Entry<Solver,Boolean> e:prior.entrySet())if(!retentionRestored){
            if(cleanup.length()>1)cleanup.append(',');cleanup.append("{\"solver_class\":").append(q(e.getKey().getClass().getName()));
            try{retain(e.getKey(),e.getValue());boolean ok=e.getValue().equals(retention(e.getKey()));cleanupOk&=ok;cleanup.append(",\"restored\":").append(ok);}
            catch(Exception restoreError){cleanupOk=false;cleanup.append(",\"restored\":false,\"error\":").append(q(restoreError.toString()));}
            cleanup.append('}');
        }
        cleanup.append(']');String deleteError=null;boolean tempClean=tmp.isEmpty();
        if(!tmp.isEmpty())try{s.deleteObjects(tmp);tmp.clear();tempClean=true;}catch(Exception cleanupError){deleteError=cleanupError.toString();cleanupOk=false;}
        if(failure!=null&&verifiedDir)try{long actual=s.getSimulationIterator().getCurrentIteration();
            write(dir,"residual-probe-failure.json","{\"status\":\"error\",\"phase\":"+q(phase)+",\"error\":"+q(failure.toString())+",\"declared_start_iteration\":"+start+",\"entry_iteration\":"+entryIteration+",\"actual_iteration\":"+actual+",\"step_attempted\":"+stepAttempted+",\"new_solver_iterations\":"+iterationDeltaJson(entryIteration,actual)+",\"cleanup_ok\":"+cleanupOk+",\"storage_restoration_results\":"+cleanup+",\"temporary_objects_cleaned\":"+tempClean+",\"temporary_cleanup_error\":"+(deleteError==null?"null":q(deleteError))+",\"engineering_verified\":false}");
        }catch(Exception recordError){s.println("Residual probe failure record could not be written: "+recordError.toString());}
    }}
}
